1	import {
2	  useLayoutEffect,
3	  useRef,
4	  useState,
5	  type ReactNode,
6	} from "react";
7	import {
8	  DESKTOP_LOGICAL_HEIGHT,
9	  DESKTOP_LOGICAL_WIDTH,
10	} from "./desktop-theme";
11	import "./desktop.css";
12	
13	interface MeasuredSize {
14	  width: number;
15	  height: number;
16	}
17	
18	export interface ScaledCanvasProps {
19	  children: ReactNode;
20	  className?: string;
21	  logicalWidth?: number;
22	  logicalHeight?: number;
23	  maxScale?: number;
24	}
25	
26	export function ScaledCanvas({
27	  children,
28	  className,
29	  logicalWidth = DESKTOP_LOGICAL_WIDTH,
30	  logicalHeight = DESKTOP_LOGICAL_HEIGHT,
31	  maxScale = Number.POSITIVE_INFINITY,
32	}: ScaledCanvasProps) {
33	  const stageRef = useRef<HTMLDivElement>(null);
34	  const [available, setAvailable] = useState<MeasuredSize>({
35	    width: 0,
36	    height: 0,
37	  });
38	
39	  useLayoutEffect(() => {
40	    const stage = stageRef.current;
41	    if (!stage) return;
42	
43	    const measure = () => {
44	      const next = {
45	        width: stage.clientWidth,
46	        height: stage.clientHeight,
47	      };
48	      setAvailable((current) =>
49	        current.width === next.width && current.height === next.height
50	          ? current
51	          : next,
52	      );
53	    };
54	
55	    measure();
56	
57	    if (typeof ResizeObserver === "undefined") {
58	      window.addEventListener("resize", measure);
59	      return () => window.removeEventListener("resize", measure);
60	    }
61	
62	    const observer = new ResizeObserver(measure);
63	    observer.observe(stage);
64	    return () => observer.disconnect();
65	  }, []);
66	
67	  const measuredScale =
68	    available.width > 0 && available.height > 0
69	      ? Math.min(
70	          available.width / logicalWidth,
71	          available.height / logicalHeight,
72	          maxScale,
73	        )
74	      : 0;
75	  const scale = Number.isFinite(measuredScale)
76	    ? Math.max(0, measuredScale)
77	    : 0;
78	
79	  const stageClassName = className
80	    ? `tapt-desktop-scale-stage ${className}`
81	    : "tapt-desktop-scale-stage";
82	
83	  return (
84	    <div ref={stageRef} className={stageClassName}>
85	      <div
86	        className="tapt-desktop-scale-box"
87	        style={{
88	          width: logicalWidth * scale,
89	          height: logicalHeight * scale,
90	          visibility: scale > 0 ? "visible" : "hidden",
91	        }}
92	      >
93	        <div
94	          className="tapt-desktop-scale-content"
95	          data-testid="desktop-scaled-canvas"
96	          data-desktop-scale={scale}
97	          style={{
98	            width: logicalWidth,
99	            height: logicalHeight,
100	            transform: `scale(${scale})`,
101	          }}
102	        >
103	          {children}
104	        </div>
105	      </div>
106	    </div>
107	  );
108	}
